class TextEditor:
    def __init__(self):
        self.l = []
        self.r = []

    def addText(self, text: str) -> None:
        for c in text:
            self.l.append(c)

    def deleteText(self, k: int) -> int:
        n = 0
        while self.l and n < k:
            self.l.pop()
            n += 1
        return n

    def _move(self, a, b, k):
        for _ in range(k):
            if not a:
                break
            b.append(a.pop())

    def cursorLeft(self, k: int) -> str:
        self._move(self.l, self.r, k)
        return ''.join(self.l[-10:])

    def cursorRight(self, k: int) -> str:
        self._move(self.r, self.l, k)
        return ''.join(self.l[-10:])

