    void move(string& a, string& b, int k) {
        while (k-- && !a.empty()) { b.push_back(a.back()); a.pop_back(); }
    }
public:
    TextEditor() {}
    void addText(string text) { for (char c : text) l.push_back(c); }
    int deleteText(int k) {
        int n = 0;
        while (k-- && !l.empty()) { l.pop_back(); n++; }
        return n;
    }
    string cursorLeft(int k) { move(l, r, k); return l.substr(max(0, (int)l.size() - 10)); }
    string cursorRight(int k) { move(r, l, k); return l.substr(max(0, (int)l.size() - 10)); }
};

