class TextEditor {
    private Deque<Character> l = new ArrayDeque<>(), r = new ArrayDeque<>();
    private void move(Deque<Character> a, Deque<Character> b, int k) {
        while (k-- > 0 && !a.isEmpty()) b.push(a.pop());
    }
    public TextEditor() {}
    public void addText(String text) { for (char c : text.toCharArray()) l.push(c); }
    public int deleteText(int k) {
        int n = 0;
        while (k-- > 0 && !l.isEmpty()) { l.pop(); n++; }
        return n;
    }
    public String cursorLeft(int k) {
        move(l, r, k);
        StringBuilder sb = new StringBuilder();
        Iterator<Character> it = l.iterator();
        for (int i = 0; i < 10 && it.hasNext(); i++) sb.insert(0, it.next());
        return sb.toString();
    }
    public String cursorRight(int k) {
        move(r, l, k);
        StringBuilder sb = new StringBuilder();
        Iterator<Character> it = l.iterator();
        for (int i = 0; i < 10 && it.hasNext(); i++) sb.insert(0, it.next());
        return sb.toString();
    }
}

