var TextEditor = function() {
    this.l = [];
    this.r = [];
};
TextEditor.prototype.addText = function(text) {
    for (const c of text) this.l.push(c);
};
TextEditor.prototype.deleteText = function(k) {
    let n = 0;
    while (this.l.length && n < k) { this.l.pop(); n++; }
    return n;
};
TextEditor.prototype.cursorLeft = function(k) {
    while (k-- > 0 && this.l.length) this.r.push(this.l.pop());
    return this.l.slice(-10).join('');
};
TextEditor.prototype.cursorRight = function(k) {
    while (k-- > 0 && this.r.length) this.l.push(this.r.pop());
    return this.l.slice(-10).join('');
};
